'use client';
import { useEffect, useMemo, useState } from 'react';
import { Activity, ArrowDownRight, ArrowRight, ArrowUpRight, BarChart3, Bell, BookOpen, BriefcaseBusiness, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Code2, Compass, FileText, FolderKanban, Gauge, GraduationCap, LayoutDashboard, Menu, MessageSquareText, MoreHorizontal, Plus, Search, Send, Settings2, Sparkles, Target, TrendingUp, Upload, Users, WandSparkles, X, Zap } from 'lucide-react';
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { applyAgentProposal } from '@/lib/agent-actions';

type Task={id:number;title:string;week:string;done:boolean;skill:string};
type Application={id:number;company:string;role:string;status:string;date:string;resume:string;skills?:string[];notes?:string;outcome?:string;roleCategory?:string;jobDescription?:string};
type Project={id:number;title:string;skills:string[];progress:number;level:string;problem?:string;why?:string;technologies?:string[];duration?:string;milestones?:string[];resume_value?:string};
type JobRecord={id:number;title:string;company:string;description:string;analysis?:any;skillGap?:any;url?:string};
type State={role:string;score:number;hours:number;skills:string[];gaps:string[];tasks:Task[];applications:Application[];projects:Project[];jobs:string[];chat:{role:string;text:string}[];interviews:number[];isDemo?:boolean;experienceLevel?:string;careerInterests?:string;resumeAnalysis?:any;jobRecords?:JobRecord[];roadmap?:any;pendingRoadmap?:any;interviewReports?:any[];interviewQuestions?:any[];applicationInsights?:any;durationWeeks?:number;pendingRoadmapChanges?:any[];pendingAgentActions?:any[];progressNotes?:any[]};
const initial:State={isDemo:true,role:'Machine Learning Engineer',score:68,hours:8,experienceLevel:'Early career',careerInterests:'Applied machine learning, responsible AI, developer tools',skills:['Python','Django','REST APIs','SQL','Git','Communication'],gaps:['TensorFlow','Model deployment','MLOps','Feature engineering'],tasks:[{id:1,title:'Complete TensorFlow fundamentals',week:'Week 1',done:true,skill:'TensorFlow'},{id:2,title:'Build your first classification model',week:'Week 1',done:false,skill:'Modeling'},{id:3,title:'Learn feature engineering patterns',week:'Week 2',done:false,skill:'Feature engineering'},{id:4,title:'Deploy a model with FastAPI',week:'Week 3',done:false,skill:'Model deployment'}],applications:[{id:1,company:'Northstar AI',role:'ML Engineer Intern',status:'Interview',date:'Oct 28',resume:'ML Engineer v2',skills:['Python','Model evaluation'],roleCategory:'Machine learning'},{id:2,company:'Linear Labs',role:'Junior ML Engineer',status:'Under review',date:'Oct 24',resume:'ML Engineer v2',skills:['TensorFlow','Python'],roleCategory:'Machine learning'},{id:3,company:'Vertex Systems',role:'Backend Engineer',status:'Applied',date:'Oct 21',resume:'Backend v1',skills:['Django','REST APIs'],roleCategory:'Backend'}],projects:[{id:1,title:'Customer churn predictor',skills:['Python','Feature engineering','Model deployment'],progress:62,level:'Intermediate'},{id:2,title:'Job description skill mapper',skills:['NLP','Python','APIs'],progress:28,level:'Advanced'}],jobs:[],jobRecords:[],chat:[],interviews:[72,78,84],interviewReports:[],interviewQuestions:[],durationWeeks:8};
const freshState:State={isDemo:false,role:'',score:0,hours:5,experienceLevel:'Student',careerInterests:'',skills:[],gaps:[],tasks:[],applications:[],projects:[],jobs:[],jobRecords:[],chat:[],interviews:[],interviewReports:[],interviewQuestions:[],durationWeeks:8};
const nav=[{section:'WORKSPACE',items:[['Dashboard',LayoutDashboard],['Career profile',Users],['Skill gap analysis',Target],['Learning roadmap',BookOpen],['Portfolio',FolderKanban],['Interview studio',MessageSquareText],['Process tracker',Activity],['Application tracker',BriefcaseBusiness]] as const},{section:'INSIGHTS',items:[['Career analytics',BarChart3],['Career agent',Sparkles]] as const}];
const trend=[{week:'Sep 23',score:42},{week:'Sep 30',score:48},{week:'Oct 07',score:53},{week:'Oct 14',score:58},{week:'Oct 21',score:64},{week:'Oct 28',score:68}];
const pages=['Dashboard','Career profile','Skill gap analysis','Learning roadmap','Portfolio','Interview studio','Process tracker','Application tracker','Career analytics','Career agent'];

export default function Home(){
 const [data,setData]=useState<State>(initial); const [page,setPage]=useState('Dashboard'); const [loaded,setLoaded]=useState(false); const [command,setCommand]=useState(''); const [busy,setBusy]=useState(false); const [agentError,setAgentError]=useState(''); const [toast,setToast]=useState(''); const [job,setJob]=useState(''); const [jobTitle,setJobTitle]=useState(''); const [jobCompany,setJobCompany]=useState(''); const [jobUrl,setJobUrl]=useState(''); const [answer,setAnswer]=useState(''); const [question,setQuestion]=useState('Tell me about a machine learning project you built. What tradeoffs did you make?'); const [mobile,setMobile]=useState(false); const [lastEvaluation,setLastEvaluation]=useState<any>(null);
 useEffect(()=>{try{const saved=localStorage.getItem('careerpilot-v1');if(saved){const restored={...initial,...JSON.parse(saved)};setData(restored);setLastEvaluation(restored.interviewReports?.at(-1)||null)};}catch{}setLoaded(true)},[]);
 useEffect(()=>{if(loaded)localStorage.setItem('careerpilot-v1',JSON.stringify(data));},[data,loaded]);
 const notify=(s:string)=>{setToast(s);window.setTimeout(()=>setToast(''),3000)};
 const completion=data.tasks.filter(t=>t.done).length; const appCount=data.applications.length; const interviews=data.applications.filter(a=>a.status==='Interview'||a.status==='Offer').length; const response=appCount?Math.round(interviews/appCount*100):0;
 const update=(patch:Partial<State>)=>setData(d=>({...d,...patch}));
 const clearHistory=()=>update({chat:[]});
 const ai=async(kind:string,payload:unknown)=>{try{const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,payload})});const j=await r.json();if(!r.ok)throw new Error(j.error||'AI request failed');return j;}catch(e){throw e;}};
 const toggleTask=(id:number)=>{const tasks=data.tasks.map(t=>t.id===id?{...t,done:!t.done}:t);const done=tasks.filter(t=>t.done).length;update({tasks,score:Math.min(99,60+Math.round(done/Math.max(tasks.length,1)*20)+Math.min(data.projects.reduce((a,p)=>a+p.progress,0)/20,10))});notify('Roadmap progress saved');};
 const addJob=async()=>{if(job.trim().length<50){notify('Add a real job description with at least 50 characters');return}setBusy(true);try{const base={description:job,title:jobTitle,company:jobCompany,url:jobUrl,profile:{role:data.role,skills:data.skills,resume:data.resumeAnalysis}};const jobResult=await ai('job_analysis',base);const gapsResult=await ai('skill_gap',{profile:{role:data.role,skills:data.skills,resume:data.resumeAnalysis},jobDescriptions:[...(data.jobs||[]),job]});const record:JobRecord={id:Date.now(),title:jobTitle||jobResult.data.jobTitle||'Untitled role',company:jobCompany||'Company not specified',description:job,analysis:jobResult.data,skillGap:gapsResult.data,url:jobUrl};update({gaps:Array.from(new Set([...data.gaps,...gapsResult.data.gaps])),jobs:[...data.jobs,job],jobRecords:[...(data.jobRecords||[]),record]});setJob('');setJobUrl('');notify('Job requirements and skill gaps analysed with Gemini')}catch(e){notify(e instanceof Error?e.message:'Could not analyse job')}finally{setBusy(false)}};
 const runCommand=async()=>{if(!command.trim()||busy)return;const text=command.trim();setBusy(true);setAgentError('');try{const context={profile:{role:data.role,skills:data.skills,gaps:data.gaps,resumeAnalysis:data.resumeAnalysis},hours:data.hours,durationWeeks:data.durationWeeks,jobRecords:(data.jobRecords||[]).slice(-8).map(j=>({...j,description:j.description.slice(0,4500)})),tasks:data.tasks,projects:data.projects,interviews:data.interviews,interviewReports:(data.interviewReports||[]).slice(-8),applications:data.applications.slice(-60),roadmap:data.roadmap,progressNotes:(data.progressNotes||[]).slice(-20)};const conversation=data.chat.slice(-12).map((m:any)=>({role:m.role,text:m.text}));const r=await fetch('/api/agent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({command:text,context,conversation})});const out=await r.json();if(!r.ok)throw new Error(out.error||'Career agent request failed');const proposals=(out.proposals||[]).map((x:any,i:number)=>({...x,id:Date.now()+i,sourceText:text}));const results=out.result||{};const interpreted=out.intent?.summary?'I understood: '+out.intent.summary+'\n\n'+out.message:out.message;update({chat:[...data.chat,{role:'user',text},{role:'assistant',text:interpreted}],pendingAgentActions:[...(data.pendingAgentActions||[]),...proposals],...(results.pendingRoadmap?{pendingRoadmap:results.pendingRoadmap}:{}),...(results.applicationInsights?{applicationInsights:results.applicationInsights}:{}),...(results.interviewQuestions?{interviewQuestions:results.interviewQuestions}:{}),...(results.progress?{pendingRoadmapChanges:results.progress.proposed_changes||[]}:{})});if(out.navigation)setPage(out.navigation);setCommand('');if(proposals.length)notify(proposals.length+' proposed action(s) ready for review');else notify('Career agent updated your saved context')}catch(e){const message=e instanceof Error?e.message:'Could not process that request';setAgentError(message);notify(message)}finally{setBusy(false)}};
 const dismissAgentAction=(id:number)=>{const action=(data.pendingAgentActions||[]).find((x:any)=>x.id===id);update({pendingAgentActions:(data.pendingAgentActions||[]).filter((x:any)=>x.id!==id),...(action?.kind==='progress_change'?{pendingRoadmapChanges:(data.pendingRoadmapChanges||[]).filter((x:any)=>JSON.stringify(x)!==JSON.stringify(action.payload))}:{})});};
 const editAgentAction=(id:number,changes:any)=>{const current=(data.pendingAgentActions||[]).find((x:any)=>x.id===id);if(!current)return;const next={...current,...changes,payload:{...current.payload,...(changes.payload||{})}};update({pendingAgentActions:(data.pendingAgentActions||[]).map((x:any)=>x.id===id?next:x),...(current.kind==='progress_change'?{pendingRoadmapChanges:(data.pendingRoadmapChanges||[]).map((x:any)=>JSON.stringify(x)===JSON.stringify(current.payload)?next.payload:x)}:{})});};
 const confirmChange=(id:number)=>{const action=(data.pendingAgentActions||[]).find((x:any)=>x.id===id);if(!action)return;let patch:Partial<State>|null;if(action.kind==='progress_change'){const p=action.payload||{};if(!acceptProgressChange(p)){notify('This suggestion no longer matches your saved plan');return}patch={pendingRoadmapChanges:(data.pendingRoadmapChanges||[]).filter((x:any)=>JSON.stringify(x)!==JSON.stringify(p))}}else patch=applyAgentProposal(data,action);if(!patch){notify('This proposed action is invalid or expired');return}setData(d=>({...d,...patch,pendingAgentActions:(d.pendingAgentActions||[]).filter((x:any)=>x.id!==id),chat:[...d.chat,{role:'assistant',text:'Confirmed: '+action.summary+'. '+(action.reason||'') }]}));notify('Confirmed change saved and reflected across CareerPilot')}; const addApplication=(item:any)=>update({applications:[{...item,id:Date.now()},...data.applications]});
 const addProject=()=>update({projects:[...data.projects,{id:Date.now(),title:'Role-ready portfolio project',skills:[...data.gaps.slice(0,2),'Python'],progress:0,level:'Intermediate'}]});
 const recommendProjects=async()=>{setBusy(true);try{const out=await ai('projects',{role:data.role,gaps:data.gaps,jobs:data.jobs,jobAnalyses:data.jobRecords?.map(j=>({title:j.title,company:j.company,analysis:j.analysis,skillGap:j.skillGap})),profile:{skills:data.skills,resume:data.resumeAnalysis}});const rows=out.data.projects||[];if(rows.length)update({projects:[...data.projects,...rows.map((p:any,i:number)=>({id:Date.now()+i,title:p.title,skills:p.skills,progress:0,level:p.difficulty||'Intermediate',problem:p.problem,why:p.why,technologies:p.technologies,duration:p.duration,milestones:p.milestones,resume_value:p.resume_value}))]});notify(`${rows.length} Gemini project recommendation${rows.length===1?'':'s'} added`)}catch(e){notify(e instanceof Error?e.message:'Could not generate projects')}finally{setBusy(false)}};
 const generateQuestions=async(settings:any={type:'mixed',difficulty:'medium',count:5})=>{setBusy(true);try{const out=await ai('interview_questions',{role:data.role,jobs:data.jobs,gaps:data.gaps,profile:data, ...settings});const questions=out.data.questions as any[];if(questions.length){update({interviewQuestions:questions});setQuestion(questions[0].question)}notify(`${questions.length} Gemini interview questions ready`)}catch(e){notify(e instanceof Error?e.message:'Could not generate questions')}finally{setBusy(false)}};
 const generateRoadmap=async()=>{setBusy(true);try{const out=await ai('roadmap',{role:data.role,hours:data.hours,durationWeeks:data.durationWeeks||8,gaps:data.gaps,profile:{skills:data.skills,resume:data.resumeAnalysis},jobs:data.jobRecords||data.jobs});const weeks=out.data.weeks as any[];const tasks=weeks.flatMap((w:any,i:number)=>(w.tasks||[]).map((title:string,j:number)=>({id:Date.now()+i*100+j,title,week:`Week ${w.week||i+1}`,done:false,skill:data.gaps[i%Math.max(data.gaps.length,1)]||'Career skill'})));update({pendingRoadmap:out.data});notify(`Gemini created a ${weeks.length}-week roadmap. Review it before applying.`)}catch(e){notify(e instanceof Error?e.message:'Could not generate roadmap')}finally{setBusy(false)}};
 const applyRoadmap=()=>{if(!data.pendingRoadmap)return;const weeks=data.pendingRoadmap.weeks||[];const tasks=weeks.flatMap((w:any,i:number)=>(w.tasks||[]).map((title:string,j:number)=>({id:Date.now()+i*100+j,title,week:`Week ${w.week||i+1}`,done:false,skill:data.gaps[i%Math.max(data.gaps.length,1)]||'Career skill'})));update({roadmap:data.pendingRoadmap,tasks,pendingRoadmap:null});notify('Your reviewed Gemini roadmap is now active')};
 const acceptProgressChange=(change:any)=>{if(change.action==='adjust_hours'&&Number.isFinite(change.hours)&&change.hours>0&&change.hours<=40){update({hours:change.hours});return true}if(change.action==='add_task'&&typeof change.title==='string'&&change.title.trim()){update({tasks:[...data.tasks,{id:Date.now(),title:change.title,week:change.week||'Week 1',done:false,skill:data.gaps[0]||'Career skill'}]});return true}if(change.action==='complete_task'&&Number.isFinite(change.taskId)&&data.tasks.some(t=>t.id===change.taskId)){update({tasks:data.tasks.map(t=>t.id===change.taskId?{...t,done:true}:t)});return true}if(change.action==='reschedule_task'&&Number.isFinite(change.taskId)&&change.week&&data.tasks.some(t=>t.id===change.taskId)){update({tasks:data.tasks.map(t=>t.id===change.taskId?{...t,week:change.week}:t)});return true}return false};
 const approveProgressChange=(change:any)=>{const ok=acceptProgressChange(change);if(ok){update({pendingRoadmapChanges:(data.pendingRoadmapChanges||[]).filter((x:any)=>x!==change)});notify('Approved roadmap adjustment applied')}else notify('This suggested adjustment no longer matches the current plan')};
 const analyzeProgress=async()=>{const result=await ai('progress',{profile:data,availableHours:data.hours,deadlineWeeks:data.durationWeeks,tasks:data.tasks,projects:data.projects,interviewReports:data.interviewReports,interviewScores:data.interviews,applications:data.applications});update({pendingRoadmapChanges:result.data.proposed_changes||[]});return result.data};
 const evaluate=async()=>{if(answer.trim().length<10){notify('Write a little more so the coach can evaluate your answer');return}setBusy(true);try{const out=await ai('interview_evaluation',{question,answer,role:data.role,jobDescriptions:data.jobs,profile:{skills:data.skills,gaps:data.gaps,resume:data.resumeAnalysis}});const report={...out.data,question,answer,createdAt:new Date().toISOString()};setLastEvaluation(report);update({interviews:[...data.interviews,out.data.overallScore],interviewReports:[...(data.interviewReports||[]),report]});notify(`Gemini evaluated your answer · ${out.data.overallScore}/100`)}catch(e){notify(e instanceof Error?e.message:'Evaluation failed')}finally{setBusy(false)}};
 const analyzeApplications=async()=>{const apps=data.applications;const responses=apps.filter(a=>!['Applied','Interested'].includes(a.status)).length;const interviewCount=apps.filter(a=>['Interview','Offer'].includes(a.status)).length;const out=await ai('application_analysis',{applications:apps,metrics:{total:apps.length,responses,responseRate:apps.length?Math.round(responses/apps.length*100):0,interviews:interviewCount,interviewConversion:apps.length?Math.round(interviewCount/apps.length*100):0,rejections:apps.filter(a=>a.status==='Rejected').length},profile:{targetRole:data.role}});update({applicationInsights:out.data});return out.data};
 const readiness=useMemo(()=>{if(data.isDemo)return data.score;const taskScore=data.tasks.length?data.tasks.filter(t=>t.done).length/data.tasks.length:0;const projectScore=data.projects.length?data.projects.reduce((sum,p)=>sum+p.progress,0)/data.projects.length/100:0;const interviewScore=data.interviews.length?data.interviews.reduce((a,b)=>a+b,0)/data.interviews.length/100:0;const hasEvidence=data.tasks.length||data.projects.length||data.interviews.length;if(!hasEvidence)return 0;return Math.round(20+taskScore*35+projectScore*20+interviewScore*25)},[data]); const latestGap=data.jobRecords?.at(-1)?.skillGap; const skillMatch=latestGap?.matchPercentage; const trendValues=useMemo(()=>{if(data.isDemo)return trend;if(!data.interviewReports?.length)return [];return data.interviewReports.slice(-6).map((r:any,i:number)=>({week:new Date(r.createdAt).toLocaleDateString(undefined,{month:'short',day:'numeric'}),score:r.overallScore}))},[data.isDemo,data.interviewReports]);
 const startFresh=()=>{if(!window.confirm('Start a clean CareerPilot workspace? This removes the sample records saved in this browser.'))return;setData(freshState);setPage('Career profile');setLastEvaluation(null);notify('Your personal workspace is ready. Add your profile to begin.')};
 return <div className="app-shell"><aside className={`sidebar ${mobile?'mobile-open':''}`}><a className="brand" href="#" onClick={e=>{e.preventDefault();setPage('Dashboard')}}><span className="brand-mark"><Compass size={20}/></span><span>career<span className="brand-light">pilot</span><small>CAREER INTELLIGENCE</small></span></a><button className="workspace" onClick={()=>setPage("Career profile")}><span className="workspace-icon">A</span><span className="workspace-copy"><b>Alex Morgan</b><small>Personal workspace</small></span><ChevronDown size={14}/></button>{nav.map(group=><div className="nav-group" key={group.section}><div className="nav-label">{group.section}</div>{group.items.map(([label,Icon])=><button key={label} className={`nav-item ${page===label?'active':''}`} onClick={()=>{setPage(label);setMobile(false)}}><Icon size={17}/><span>{label}</span>{label==='Application tracker'&&<i>{appCount}</i>}</button>)}</div>)}<div className="sidebar-bottom"><div className="upgrade-card"><div className="upgrade-icon"><Zap size={16}/></div><b>Your next move is closer.</b><p>Small steps compound into career momentum.</p><button onClick={()=>setPage('Learning roadmap')}>View your roadmap <ArrowRight size={13}/></button></div><button className="nav-item" onClick={()=>setPage('Career profile')}><Settings2 size={17}/><span>Settings</span></button><div className="sidebar-user"><div className="avatar">AM</div><span><b>Alex Morgan</b><small>Free plan</small></span><MoreHorizontal size={18}/></div></div></aside>
 <main className="main"><header className="topbar"><button className="icon-button mobile-menu" onClick={()=>setMobile(!mobile)} aria-label="Toggle navigation"><Menu size={18}/></button><div className="breadcrumbs"><span>Workspace</span><ChevronRight size={13}/><b>{page}</b></div><div className="top-actions">{data.isDemo&&<button className="tag-chip" onClick={startFresh} title="Replace sample content with your own profile">DEMO DATA · START YOURS</button>}<button className="help-button" onClick={()=>setPage('Career agent')}><CircleHelp size={16}/><span>Career guide</span></button><button className="icon-button notification" aria-label="Open application tracker" onClick={()=>setPage('Application tracker')}><Bell size={17}/><i/></button><div className="avatar top-avatar">AM</div></div></header>
 <div className="page-content"><div className="page-heading"><div><div className="eyebrow"><span className="live-dot"/> YOUR CAREER, IN MOTION</div><h1>{page==='Dashboard'?(data.isDemo?'Good morning, Alex':'Your career command centre'):page}</h1><p>{page==='Dashboard'?(data.isDemo?'Here’s your career momentum at a glance. Sample records are labelled as demo data.':'Your saved profile and activity, in one place.'):'A clear view of your next move'+(data.role?' as a '+data.role:'')+'.'}</p></div><span className="date-pill"><CalendarDays size={15}/> {new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</span></div>
 {page==='Dashboard'&&data.isDemo&&<div className="surface intro-banner"><span className="metric-icon purple"><CircleHelp size={18}/></span><div><h2>Explore with sample data</h2><p>These realistic records demonstrate the workflow. Start your own workspace to see only your information.</p></div><button className="primary-button" onClick={startFresh}>Start with my profile <ArrowRight size={14}/></button></div>}
 {page==='Dashboard'&&<><section className="command-card"><div className="command-top"><span className="command-icon"><Sparkles size={17}/></span><div><b>Your career agent</b><span>Tell me what’s on your mind. I’ll help you make a plan.</span></div><span className="agent-online"><i/> READY</span></div><div className="command-input"><input value={command} onChange={e=>setCommand(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')runCommand()}} placeholder="Try “I have 8 hours a week to prepare for ML roles…”"/><button className="send-button" onClick={runCommand} disabled={busy}>{busy?<span className="spinner"/>:<Send size={15}/>}</button></div><div className="command-foot"><span><span className="key">↵</span> to send</span><button className="text-action" onClick={()=>setPage('Career agent')}>Open conversation <ArrowRight size={12}/></button></div></section>
 <section className="metric-grid"><div className="metric-card readiness-card"><div className="metric-top"><span>CAREER READINESS</span><span className="metric-menu"><MoreHorizontal size={17}/></span></div><div className="readiness-content"><div className="ring" style={{'--progress':`${readiness*3.6}deg`} as React.CSSProperties}><div><b>{readiness}</b><small>/ 100</small></div></div><div><div className="trend-label"><ArrowUpRight size={14}/> +12 pts</div><p>vs. last month</p><span className="small-copy">You’re building real momentum</span></div></div><div className="metric-bottom"><span>Target role</span><b>{data.role}<ChevronDown size={13}/></b></div></div><div className="metric-card"><div className="metric-top"><span>SKILL MATCH</span><span className="metric-icon blue"><Target size={16}/></span></div><div className="big-stat">{typeof skillMatch==="number"?skillMatch:"—"}{typeof skillMatch==="number"&&<span>%</span>}</div><div className="stat-note">{typeof skillMatch==="number"?"From your latest supplied job analysis":"Add a job description for a measured match"}</div><div className="mini-bars">{[38,50,43,68,55,73,66,86,61,79,70,94].map((n,i)=><i key={i} style={{height:`${n}%`}}/>)}</div></div><div className="metric-card"><div className="metric-top"><span>LEARNING THIS WEEK</span><span className="metric-icon purple"><BookOpen size={16}/></span></div><div className="big-stat">{completion}<span className="stat-divider">/</span>{data.tasks.length}</div><div className="stat-note">tasks completed <span className="neutral-note">· {data.hours}h weekly goal</span></div><div className="progress-track"><i style={{width:`${completion/Math.max(data.tasks.length,1)*100}%`}}/></div><div className="metric-bottom subtle"><span>Next up</span><b>{data.tasks.find(t=>!t.done)?.title||'All caught up'} <ArrowRight size={13}/></b></div></div><div className="metric-card"><div className="metric-top"><span>APPLICATIONS</span><span className="metric-icon green"><BriefcaseBusiness size={16}/></span></div><div className="big-stat">{appCount}<span className="stat-label">active</span></div><div className="stat-note"><span className="trend-mini">{interviews} interviews</span> · {response}% conversion</div><div className="application-mini"><div className="app-avatars"><span>N</span><span>L</span><span>V</span></div><span>Latest activity <b>2 days ago</b></span></div></div></section>
 <section className="main-grid"><div className="surface readiness-chart"><div className="section-head"><div><h2>Readiness over time</h2><p>Your progress is adding up.</p></div><span className="select-pill">{data.isDemo?"Sample · 6 weeks":"Interview history"}</span></div><div className="chart-key"><i/> Readiness score <span>Target role · {data.role}</span></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trendValues} margin={{top:10,right:4,left:-22,bottom:0}}><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#78836b" stopOpacity={0.21}/><stop offset="95%" stopColor="#78836b" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#dfdbd1" strokeDasharray="3 5" vertical={false}/><XAxis dataKey="week" axisLine={false} tickLine={false} tick={{fill:'#77766d',fontSize:10}} dy={9}/><YAxis domain={[30,100]} axisLine={false} tickLine={false} tick={{fill:'#77766d',fontSize:10}}/><Tooltip contentStyle={{background:'#fffdf8',border:'1px solid #d8d3c8',borderRadius:8,color:'#34372f'}}/><Area type="monotone" dataKey="score" stroke="#6d795e" strokeWidth={2.2} fill="url(#chartFill)" activeDot={{r:5,fill:'#9a7b52',stroke:'#fbfaf6',strokeWidth:3}}/></AreaChart></ResponsiveContainer></div><div className="chart-footer"><span><TrendingUp size={14}/> Steady progress</span><span>Sample trend until you record progress</span></div></div><div className="surface focus-card"><div className="section-head"><div><h2>Your focus areas</h2><p>High impact skills for your target role.</p></div><button className="text-action" onClick={()=>setPage('Skill gap analysis')}>View all <ArrowRight size={13}/></button></div>{data.gaps.slice(0,4).map((skill,i)=><div className="focus-row" key={skill}><span className={`focus-symbol f${i}`}><Code2 size={15}/></span><span className="focus-info"><b>{skill}</b><small>{i===0?'Critical gap':i===1?'High priority':'Build proficiency'}</small></span><span className={`priority p${i<2?'high':'med'}`}>{i<2?'HIGH':'MED'}</span><span className="skill-line"><i style={{width:`${[25,40,55,35][i]}%`}}/></span></div>)}<button className="focus-cta" onClick={()=>setPage('Learning roadmap')}><span>Turn gaps into a plan</span><ArrowRight size={14}/></button></div></section>
 <section className="lower-grid"><div className="surface roadmap-card"><div className="section-head"><div><h2>This week’s roadmap</h2><p>{completion} of {data.tasks.length} milestones complete <span className="week-badge">WEEK 1</span></p></div><button className="text-action" onClick={()=>setPage('Learning roadmap')}>Full roadmap <ArrowRight size={13}/></button></div><div className="task-list">{data.tasks.slice(0,3).map(t=><button key={t.id} className={`task-row ${t.done?'task-done':''}`} onClick={()=>toggleTask(t.id)}><span className={`check-circle ${t.done?'checked':''}`}>{t.done&&<Check size={12}/>}</span><span className="task-name">{t.title}<small><Clock3 size={11}/> {t.done?'Completed':t.week+' · '+t.skill}</small></span><span className={t.done?'status-complete':'status-upcoming'}>{t.done?'DONE':'UP NEXT'}</span></button>)}</div><button className="roadmap-link" onClick={()=>setPage('Learning roadmap')}>Continue learning <ArrowRight size={14}/></button></div><div className="surface activity-card"><div className="section-head"><div><h2>Recent activity</h2><p>Your latest career moves.</p></div><button className="icon-button small"><MoreHorizontal size={17}/></button></div><div className="activity-list"><div className="activity-row"><span className="activity-icon ai"><BriefcaseBusiness size={14}/></span><div><b>Interview invitation</b><p>Northstar AI · ML Engineer Intern</p><small>2 days ago</small></div><span className="activity-dot green-dot"/></div><div className="activity-row"><span className="activity-icon learning"><CheckCircle2 size={14}/></span><div><b>Milestone completed</b><p>TensorFlow fundamentals</p><small>3 days ago</small></div><span className="activity-dot purple-dot"/></div><div className="activity-row"><span className="activity-icon project"><FolderKanban size={14}/></span><div><b>Project milestone</b><p>Churn predictor · Model training</p><small>5 days ago</small></div><span className="activity-dot blue-dot"/></div></div></div></section></>}
 {page==='Career profile'&&<Profile data={data} update={update} notify={notify}/>}{page==='Skill gap analysis'&&<SkillGap data={data} setPage={setPage} job={job} setJob={setJob} title={jobTitle} setTitle={setJobTitle} company={jobCompany} setCompany={setJobCompany} jobUrl={jobUrl} setJobUrl={setJobUrl} addJob={addJob} busy={busy}/>}{page==='Learning roadmap'&&<Roadmap data={data} toggle={toggleTask} hours={data.hours} changeHours={(n:number)=>update({hours:n})} setDuration={(n:number)=>update({durationWeeks:n})} generate={generateRoadmap} apply={applyRoadmap} discard={()=>update({pendingRoadmap:null})} busy={busy}/>}{page==='Portfolio'&&<Projects data={data} add={addProject} recommend={recommendProjects} busy={busy} update={(projects:Project[])=>update({projects})}/>}{page==='Interview studio'&&<Interview question={question} setQuestion={setQuestion} answer={answer} setAnswer={setAnswer} evaluate={evaluate} generate={generateQuestions} busy={busy} scores={data.interviews} role={data.role} evaluation={lastEvaluation} questions={data.interviewQuestions} reports={data.interviewReports}/>}{page==='Process tracker'&&<ProcessTracker data={data} toggle={toggleTask} setPage={setPage} changeHours={(hours:number)=>update({hours})} analyzeProgress={analyzeProgress} approveChange={approveProgressChange} dismissChange={(change:any)=>update({pendingRoadmapChanges:(data.pendingRoadmapChanges||[]).filter((x:any)=>x!==change)})}/>}{page==='Application tracker'&&<Applications data={data} add={addApplication} update={(applications:Application[])=>update({applications})}/>}{page==='Career analytics'&&<Analytics data={data} response={response} interviews={interviews} setPage={setPage} analyze={analyzeApplications} busy={busy}/>}{page==='Career agent'&&<Agent data={data} command={command} setCommand={setCommand} run={runCommand} confirm={confirmChange} dismiss={dismissAgentAction} edit={editAgentAction} clearHistory={clearHistory} busy={busy} error={agentError}/>}
 </div></main>{toast&&<div className="toast"><CheckCircle2 size={16}/>{toast}<button onClick={()=>setToast('')}><X size={14}/></button></div>}
 </div>
}

function Profile({data,update,notify}:any){
 const [role,setRole]=useState(data.role);const [skills,setSkills]=useState(data.skills.join(', '));const [resume,setResume]=useState('');const [analysis,setAnalysis]=useState<any>(data.resumeAnalysis||null);const [busy,setBusy]=useState(false);const [duration,setDuration]=useState(data.durationWeeks||8);const [experienceLevel,setExperienceLevel]=useState(data.experienceLevel||'Student');const [careerInterests,setCareerInterests]=useState(data.careerInterests||'');
const saveAnalysis=(value:any)=>setAnalysis(value);
 const runResumeAnalysis=async()=>{if(resume.trim().length<40){notify('Paste at least a few lines of resume text first');return}setBusy(true);try{const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:'resume_analysis',payload:{resume,targetRole:role}})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Resume analysis failed');saveAnalysis(j.data);notify('Resume analysed with Gemini. Review the extracted fields below.')}catch(e){notify(e instanceof Error?e.message:'Resume analysis failed')}finally{setBusy(false)}};
 const uploadResume=async(file?:File)=>{if(!file)return;if(file.size>10*1024*1024){notify('Resume must be 10 MB or smaller');return}if(!/\.(pdf|docx)$/i.test(file.name)){notify('Choose a PDF or DOCX resume');return}setBusy(true);try{const form=new FormData();form.append('file',file);form.append('role',role);const r=await fetch('/api/resume',{method:'POST',body:form});const j=await r.json();if(!r.ok)throw new Error(j.error||'Resume upload failed');saveAnalysis(j.data);notify('Resume extracted and analysed with Gemini. Review the fields before saving.')}catch(e){notify(e instanceof Error?e.message:'Resume upload failed')}finally{setBusy(false)}};
 const editArray=(key:string,value:string)=>setAnalysis((current:any)=>({...current,[key]:value.split('\n').map(x=>x.trim()).filter(Boolean)}));
 return <><div className="two-col"><div className="surface form-surface"><div className="section-head"><div><h2>Your career profile</h2><p>Keep your experience and ambitions current.</p></div><span className="saved-badge"><CheckCircle2 size={13}/> SAVED LOCALLY</span></div><label className="field-label">TARGET ROLE<input value={role} onChange={e=>setRole(e.target.value)} /></label><label className="field-label">SKILLS, COMMA SEPARATED<input value={skills} onChange={e=>setSkills(e.target.value)} /></label><label className="field-label">PREPARATION DEADLINE (WEEKS)<input type="number" min="1" max="52" value={duration} onChange={e=>setDuration(Math.max(1,Number(e.target.value)||1))}/></label><label className="field-label">EXPERIENCE LEVEL<select value={experienceLevel} onChange={e=>setExperienceLevel(e.target.value)}><option>Student</option><option>Early career</option><option>Mid-level</option><option>Senior</option></select></label><label className="field-label">CAREER INTERESTS<textarea value={careerInterests} onChange={e=>setCareerInterests(e.target.value)} rows={3}/></label><button className="primary-button" onClick={()=>{update({role,durationWeeks:duration,experienceLevel,careerInterests,skills:skills.split(',').map((x:string)=>x.trim()).filter(Boolean)});notify('Profile saved')}}>Save profile <Check size={15}/></button></div><div className="surface resume-surface"><div className="section-head"><div><h2>Resume intelligence</h2><p>Extract and review structured experience with Gemini.</p></div><span className="resume-icon"><FileText size={17}/></span></div><div className="upload-box"><Upload size={20}/><b>Upload a PDF or DOCX resume</b><span>Up to 10 MB · files are parsed server-side for this request</span><label className="secondary-button">{busy?'Analysing…':'Choose resume'}<input hidden type="file" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" disabled={busy} onChange={e=>uploadResume(e.target.files?.[0])}/></label></div><div className="or-divider"><span>OR PASTE RESUME TEXT</span></div><textarea className="resume-text" placeholder="Paste resume text here for structured Gemini analysis…" value={resume} onChange={e=>setResume(e.target.value)}/><button className="primary-button full" onClick={runResumeAnalysis} disabled={busy}>{busy?<><span className="spinner"/> Analysing…</>:<><WandSparkles size={15}/> Analyse pasted resume</>}</button>{analysis&&<div className="analysis-result"><div className="section-head"><div><b>Review extracted information</b><p>Make corrections, then save it to your career profile.</p></div><span className="tag-chip">GEMINI ANALYSIS</span></div><p className="resume-summary">{analysis.summary}</p>{(['education','experience','skills','achievements'] as const).map(key=><label className="field-label" key={key}>{key.toUpperCase()}<textarea rows={Math.min(5,Math.max(2,(analysis[key]||[]).length))} value={(analysis[key]||[]).join('\n')} onChange={e=>editArray(key,e.target.value)}/></label>)}<label className="field-label">PROJECTS<textarea rows={4} value={(analysis.projects||[]).map((p:any)=>p.title+': '+p.description+' ['+(p.skills||[]).join(', ')+']').join('\n')} onChange={e=>setAnalysis((current:any)=>({...current,projects:e.target.value.split('\n').filter(Boolean).map((line:string)=>({title:line.split(':')[0],description:line.split(':').slice(1).join(':').split('[')[0].trim(),skills:(line.match(/\[(.*)\]/)?.[1]||'').split(',').map((x:string)=>x.trim()).filter(Boolean)}))}))}/></label><button className="primary-button" onClick={()=>{const profileSkills=Array.from(new Set([...data.skills,...(analysis.skills||[])]));update({role,experienceLevel,careerInterests,skills:profileSkills,resumeAnalysis:analysis});setSkills(profileSkills.join(', '));notify('Reviewed resume details saved to your profile')}}><Check size={14}/> Save reviewed profile</button></div>}</div></div></>}

function SkillGap({data,setPage,job,setJob,title,setTitle,company,setCompany,jobUrl,setJobUrl,addJob,busy}:any){
 const records=data.jobRecords||[];const analysis=records.at(-1)?.skillGap;const rows=[...(analysis?.missingSkills||[]),...(analysis?.improvingSkills||[])];
 const [filter,setFilter]=useState('All');const filtered=filter==='All'?rows:rows.filter((x:any)=>x.category?.toLowerCase()===filter.toLowerCase());const match=analysis?.matchPercentage;
 return <><div className="surface intro-banner"><span className="metric-icon purple"><Target size={18}/></span><div><h2>{records.length?'Requirements across '+records.length+' supplied roles':'Build your evidence-based skill map'}</h2><p>{records.length?'Gemini analysis of real job descriptions you provided.':'Add job postings to compare requirements with your profile.'}</p></div><button className="secondary-button" onClick={()=>document.getElementById('job-input')?.focus()}><Plus size={15}/> Add job description</button></div>
 <div className="skill-overview"><div className="surface match-card"><span>OVERALL SKILL MATCH</span><div className="match-num">{typeof match==='number'?match:'—'}<span>{typeof match==='number'?'%':''}</span></div><div className="progress-track"><i style={{width:(match||0)+'%'}}/></div><p>{analysis?.summary||'Analysis will appear after adding a real job description.'}</p><div className="match-legend"><span>{analysis?.matchedSkills?.length||0} matched skills</span><span>{analysis?.missingSkills?.length||data.gaps.length} gaps identified</span></div></div>
 <div className="surface skill-breakdown"><div className="section-head"><div><h2>Skill gap map</h2><p>Priority, proficiency and evidence from supplied postings.</p></div><select className="select-pill" value={filter} onChange={e=>setFilter(e.target.value)}><option>All</option><option>Technical</option><option>Non-technical</option><option>Tool</option></select></div>{filtered.length?filtered.map((x:any,i:number)=><div className="gap-row" key={x.name+i}><span className="gap-rank">{i+1}</span><span className="gap-skill"><b>{x.name}</b><small>{x.category||'Skill'} · frequency {x.frequency||0} · {x.evidence||'No explicit evidence'} · target {x.recommendedProficiency||'proficient'}</small></span><span className="priority">{x.importance||'MED'}</span></div>):<div className="empty-chat"><b>No analysed skills yet</b><p>Supply a posting and Gemini will compare it against your saved profile.</p></div>}</div></div>
 {analysis?.matchedSkills?.length>0&&<div className="surface skill-breakdown"><h2>Skills already evidenced</h2><p>Requirements with supporting evidence in your supplied profile.</p><div className="tag-list">{analysis.matchedSkills.map((x:any)=><span className="tag-chip" key={x.name}>{x.name} · {x.currentProficiency||"matched"}</span>)}</div></div>}
 {records.length>0&&<div className="surface skill-breakdown"><h2>Supplied job descriptions</h2>{records.map((r:JobRecord)=><details key={r.id}><summary>{r.title} · {r.company}</summary><p>{r.analysis?.summary}</p><div className="tag-list">{(r.analysis?.requiredSkills||[]).map((x:any)=><span className="tag-chip" key={x.name}>{x.name} · {x.importance}</span>)}</div><p>{r.analysis?.responsibilities?.join(' · ')}</p></details>)}</div>}
 <div className="surface job-import"><div className="section-head"><div><h2>Analyse a job description</h2><p>Bring a real posting into focus.</p></div><span className="source-note"><CircleHelp size={13}/> Only analyses content you provide</span></div><div className="job-meta"><input placeholder="Job title (optional)" value={title} onChange={e=>setTitle(e.target.value)}/><input placeholder="Company (optional)" value={company} onChange={e=>setCompany(e.target.value)}/><input placeholder="Original job URL (optional)" value={jobUrl} onChange={e=>setJobUrl(e.target.value)}/></div><textarea id="job-input" value={job} onChange={e=>setJob(e.target.value)} placeholder="Paste job description…" rows={5}/><div className="job-footer"><span>{job.length} characters · Stored in this browser</span><button className="primary-button" onClick={addJob} disabled={busy}>{busy?<span className="spinner"/>:<WandSparkles size={15}/>} Analyse requirements</button></div></div></>}
function Roadmap({data,toggle,hours,changeHours,generate,apply,discard,setDuration,busy}:any){
 const weeks=data.roadmap?.weeks||[];
 return <><div className="intro-banner surface"><span className="metric-icon blue"><GraduationCap size={18}/></span><div><h2>{weeks.length?'Your '+weeks.length+'-week learning plan':'Build a personalised learning plan'}</h2><p>Gemini tailors objectives to {data.role}, job evidence and {hours} study hours per week.</p></div><button className="secondary-button" onClick={generate} disabled={busy}>{busy?<span className="spinner"/>:<WandSparkles size={14}/>} Generate with AI</button><div className="hours-control"><button onClick={()=>changeHours(Math.max(1,hours-1))}>−</button><b>{hours}h / wk</b><button onClick={()=>changeHours(Math.min(40,hours+1))}>+</button></div></div><div className="surface job-import"><label className="field-label">PREPARATION DEADLINE (WEEKS)<input type="number" min="1" max="52" value={data.durationWeeks||8} onChange={e=>setDuration(Number(e.target.value))}/></label><p className="capacity-note">{hours*(data.durationWeeks||8)} available study hours before target date.</p></div>
 {data.pendingRoadmap&&<div className="surface week-card"><div className="section-head"><div><span className="tag-chip">GEMINI PROPOSAL</span><h2>Review before applying</h2><p>The active plan remains unchanged until you accept this proposal.</p></div><div className="table-actions"><button className="secondary-button" onClick={discard}>Discard</button><button className="primary-button" onClick={apply}><Check size={14}/> Apply roadmap</button></div></div>{data.pendingRoadmap.weeks.map((w:any)=><div className="week-heading" key={w.week}><div><span className="week-badge">WEEK {w.week}</span><h3>{w.objective}</h3><p>{w.milestone}</p><small>{w.tasks.join(' · ')}</small><div className="tag-list">{w.resources.map((r:string)=><span className="tag-chip" key={r}>{r}</span>)}</div></div><span className="week-time">{w.hours} hours</span></div>)}</div>}
 {weeks.length?weeks.map((w:any)=><div className="surface week-card" key={w.week}><div className="week-heading"><div><span className="week-badge">WEEK {w.week}</span><h2>{w.objective}</h2><p>{w.milestone}</p></div><span className="week-time"><Clock3 size={14}/> {w.hours} hours</span></div>{w.tasks.map((title:string)=><button className="task-row roadmap-task" key={title} onClick={()=>{const t=data.tasks.find((x:Task)=>x.title===title);if(t)toggle(t.id)}}><span className="check-circle">{data.tasks.find((x:Task)=>x.title===title)?.done&&<Check size={12}/>}</span><span className="task-name">{title}<small>{data.gaps?.[0]||'Career skill'}</small></span></button>)}<div className="tag-list">{w.resources.map((r:string)=><span className="tag-chip" key={r}>{r}</span>)}</div></div>):<div className="surface empty-chat"><b>No active AI roadmap yet</b><p>Generate weekly objectives and resources grounded in your gaps and deadline.</p><button className="primary-button" onClick={generate} disabled={busy}><Sparkles size={14}/> Create my roadmap</button></div>}</>}
function Projects({data,add,recommend,busy,update}:any){return <><div className="section-toolbar"><div><p>Portfolio work mapped directly to your skill gaps.</p></div><div className="table-actions"><button className="secondary-button" onClick={recommend} disabled={busy}>{busy?<span className="spinner"/>:<Sparkles size={14}/>} Recommend with AI</button><button className="primary-button" onClick={add}><Plus size={15}/> Add project</button></div></div><div className="project-grid">{data.projects.map((p:Project,i:number)=><article className="surface project-card" key={p.id}><div className="project-top"><span className={`project-art art${i%3}`}><Code2 size={23}/></span><button className="icon-button small" onClick={()=>update(data.projects.filter((x:Project)=>x.id!==p.id))}><MoreHorizontal size={17}/></button></div><span className="project-kicker">{p.level.toUpperCase()} · PORTFOLIO PROJECT</span><h2>{p.title}</h2><p>{p.problem||p.why||"Demonstrate practical capability in skills for your target roles."}</p>{p.technologies&&p.technologies.length>0&&<p><b>Stack:</b> {p.technologies.join(", ")}</p>}{p.duration&&<small>Estimated effort: {p.duration}</small>}{p.resume_value&&<p><b>Career value:</b> {p.resume_value}</p>}<div className="tag-list">{p.skills.map(s=><span className="tag-chip" key={s}>{s}</span>)}</div><div className="project-progress"><div><span>Progress</span><b>{p.progress}%</b></div><div className="progress-track"><i style={{width:`${p.progress}%`}}/></div></div><button className="project-action" onClick={()=>update(data.projects.map((x:Project)=>x.id===p.id?{...x,progress:Math.min(100,x.progress+20)}:x))}>{p.progress>=100?'Completed':'Update progress'} <ArrowRight size={14}/></button></article>)}</div></>}
function Interview({question,setQuestion,answer,setAnswer,evaluate,generate,busy,scores,role,evaluation,questions,reports}:any){
 const [type,setType]=useState('mixed');const [difficulty,setDifficulty]=useState('medium');const [count,setCount]=useState(5);
 return <><div className="intro-banner surface"><span className="metric-icon purple"><MessageSquareText size={18}/></span><div><h2>Practice with purpose</h2><p>Questions grounded in your {role} target and analysed job requirements.</p></div><select className="select-pill" value={type} onChange={e=>setType(e.target.value)}><option value="mixed">Mixed</option><option value="technical">Technical</option><option value="behavioural">Behavioural</option></select><select className="select-pill" value={difficulty} onChange={e=>setDifficulty(e.target.value)}><option value="easy">Easy</option><option value="medium">Medium</option><option value="hard">Hard</option></select><select className="select-pill" value={count} onChange={e=>setCount(Number(e.target.value))}><option value={3}>3 questions</option><option value={5}>5 questions</option><option value={8}>8 questions</option></select><button className="secondary-button" onClick={()=>generate({type,difficulty,count})} disabled={busy}>{busy?<span className="spinner"/>:<Sparkles size={14}/>} Generate questions</button></div>
 <div className="interview-layout"><div className="surface interview-session"><div className="session-top"><span><i className="live-dot"/> {questions?.length?'QUESTION 1 OF '+questions.length:'READY'}</span><span>{type.toUpperCase()} · {difficulty.toUpperCase()}</span></div><h2>{question}</h2><div className="question-context"><Sparkles size={14}/><span>{questions?.[0]?.why||'Generate a set to ground interview questions in your supplied job descriptions and skill gaps.'}</span></div><label className="field-label answer-label">YOUR ANSWER<textarea rows={8} placeholder="Structure your thinking, then explain your approach…" value={answer} onChange={e=>setAnswer(e.target.value)}/></label><div className="session-footer"><button className="text-action" onClick={()=>{const i=questions?.findIndex((q:any)=>q.question===question)??-1;const next=questions?.[(i+1)%questions.length];if(next)setQuestion(next.question);setAnswer('')}}>Next question <ArrowRight size={14}/></button><button className="primary-button" onClick={evaluate} disabled={busy}>{busy?'Evaluating…':'Evaluate answer'} <ArrowRight size={14}/></button></div></div><div className="surface coach-panel"><span className="coach-icon"><Sparkles size={17}/></span><h3>Interview coach</h3><p>Answer evaluation returns a five-part rubric and actionable feedback.</p><div className="last-score"><div><span>SAVED PRACTICE SCORES</span><b>{scores.slice(-3).reverse().join(' · ')||'No evaluated answers yet'}</b></div></div></div></div>
 {evaluation&&<div className="surface eval-result"><div className="section-head"><div><h2>Gemini answer evaluation</h2><p>Saved {new Date(evaluation.createdAt).toLocaleString()}</p></div><strong className="eval-score">{evaluation.overallScore}<small>/100</small></strong></div><p>{evaluation.feedback?.join(' ')}</p><div className="eval-columns"><div><b>Strengths</b>{evaluation.strengths?.map((x:string)=><p key={x}>✓ {x}</p>)}</div><div><b>Areas to improve</b>{evaluation.weaknesses?.map((x:string)=><p key={x}>→ {x}</p>)}</div></div><div className="tag-list">{Object.entries(evaluation.rubric||{}).map(([k,v])=><span className="tag-chip" key={k}>{k.replaceAll('_',' ')}: {String(v)}/100</span>)}</div><div className="strong-answer"><b>Example stronger answer</b><p>{evaluation.stronger_answer}</p><small>Topics to revisit: {evaluation.topics?.join(', ')}</small></div></div>}
 {reports?.length>0&&<div className="surface analytics-card"><h2>Interview history</h2>{reports.slice(-5).reverse().map((r:any,i:number)=><details key={r.createdAt+i}><summary>{r.question} · {r.overallScore}/100</summary><p>{r.feedback?.join(' ')}</p></details>)}</div>}</>}
function Applications({data,add,update}:any){
 const statuses=['Interested','Applied','Under review','Interview','Offer','Rejected'];const [open,setOpen]=useState(false);
 const [form,setForm]=useState<any>({company:'',role:'',date:new Date().toISOString().slice(0,10),resume:'',skills:'',status:'Interested',jobDescription:'',notes:''});
 const save=()=>{if(!form.company.trim()||!form.role.trim())return;add({...form,date:form.date,resume:form.resume||'CareerPilot profile',skills:form.skills.split(',').map((x:string)=>x.trim()).filter(Boolean),roleCategory:form.role});setForm({...form,company:'',jobDescription:'',notes:''});setOpen(false)};
 const edit=(id:number,key:string,value:string)=>update(data.applications.map((a:Application)=>a.id===id?{...a,[key]:value}:a));
 return <><div className="metric-grid small-metrics"><div className="metric-card"><div className="metric-top"><span>TOTAL APPLICATIONS</span><BriefcaseBusiness size={16}/></div><div className="big-stat">{data.applications.length}</div><div className="stat-note">Tracked opportunities</div></div><div className="metric-card"><div className="metric-top"><span>RESPONSE RATE</span><Activity size={16}/></div><div className="big-stat">{data.applications.length?Math.round(data.applications.filter((a:Application)=>!['Applied','Interested'].includes(a.status)).length/data.applications.length*100):0}<span>%</span></div><div className="stat-note">Observed recorded responses</div></div><div className="metric-card"><div className="metric-top"><span>INTERVIEW CONVERSION</span><MessageSquareText size={16}/></div><div className="big-stat">{data.applications.length?Math.round(data.applications.filter((a:Application)=>['Interview','Offer'].includes(a.status)).length/data.applications.length*100):0}<span>%</span></div><div className="stat-note">Interview or offer outcomes</div></div><div className="metric-card"><div className="metric-top"><span>OFFERS</span><CheckCircle2 size={16}/></div><div className="big-stat">{data.applications.filter((a:Application)=>a.status==='Offer').length}</div><div className="stat-note">From tracked applications</div></div></div>
 <div className="surface table-surface"><div className="section-head"><div><h2>Application pipeline</h2><p>Demo rows are labelled; your edits persist in this browser.</p></div><div className="table-actions"><button className="primary-button" onClick={()=>setOpen(!open)}><Plus size={15}/> Add application</button></div></div>
 {open&&<div className="job-import"><div className="job-meta"><input placeholder="Company" value={form.company} onChange={e=>setForm({...form,company:e.target.value})}/><input placeholder="Job title" value={form.role} onChange={e=>setForm({...form,role:e.target.value})}/><input type="date" value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/><input placeholder="Resume version" value={form.resume} onChange={e=>setForm({...form,resume:e.target.value})}/><select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{statuses.map(x=><option key={x}>{x}</option>)}</select><input placeholder="Emphasised skills, comma separated" value={form.skills} onChange={e=>setForm({...form,skills:e.target.value})}/></div><textarea rows={3} placeholder="Paste or link notes about this role / job description" value={form.jobDescription} onChange={e=>setForm({...form,jobDescription:e.target.value})}/><textarea rows={2} placeholder="Notes" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/><button className="primary-button" onClick={save} disabled={!form.company.trim()||!form.role.trim()}>Save application</button></div>}
 <div className="table-scroll"><table><thead><tr><th>COMPANY</th><th>ROLE</th><th>DATE</th><th>RESUME</th><th>STATUS</th><th></th></tr></thead><tbody>{data.applications.map((a:Application)=><tr key={a.id}><td><span className="company-cell"><span>{a.company?.[0]||'?'}</span><b>{a.company}</b></span>{data.isDemo&&a.id<=3&&<small>Sample data</small>}</td><td>{a.role}</td><td>{a.date}</td><td><input aria-label="Resume version" value={a.resume} onChange={e=>edit(a.id,'resume',e.target.value)}/></td><td><select className={'status-select '+a.status.toLowerCase().replaceAll(' ','-')} value={a.status} onChange={e=>edit(a.id,'status',e.target.value)}>{statuses.map(x=><option key={x}>{x}</option>)}</select></td><td><button className="icon-button small" aria-label="Delete application" onClick={()=>update(data.applications.filter((x:Application)=>x.id!==a.id))}><X size={14}/></button></td></tr>)}</tbody></table></div>{data.applications.length===0&&<p className="empty-chat">Add an application to begin building your outcome history.</p>}</div></>}
function Analytics({data,response,interviews,setPage,analyze,busy}:any){
 const [error,setError]=useState('');const run=async()=>{setError('');try{await analyze()}catch(e){setError(e instanceof Error?e.message:'Gemini analysis failed')}};
 const insights=data.applicationInsights;const total=data.applications.length;const responseCount=data.applications.filter((a:Application)=>!['Applied','Interested'].includes(a.status)).length;
 return <><div className="metric-grid small-metrics"><div className="metric-card"><div className="metric-top"><span>APPLICATIONS</span><BriefcaseBusiness size={16}/></div><div className="big-stat">{total}</div><div className="stat-note">Tracked opportunities</div></div><div className="metric-card"><div className="metric-top"><span>RESPONSE RATE</span><ArrowUpRight size={16}/></div><div className="big-stat">{total?Math.round(responseCount/total*100):0}<span>%</span></div><div className="stat-note">Recorded responses</div></div><div className="metric-card"><div className="metric-top"><span>INTERVIEW CONVERSION</span><MessageSquareText size={16}/></div><div className="big-stat">{response}<span>%</span></div><div className="stat-note">{interviews} interview or offer outcomes</div></div><div className="metric-card"><div className="metric-top"><span>INTERVIEW AVERAGE</span><Target size={16}/></div><div className="big-stat">{data.interviews.length?Math.round(data.interviews.reduce((a:number,b:number)=>a+b,0)/data.interviews.length):'—'}<span>{data.interviews.length?'/100':''}</span></div><div className="stat-note">Evaluated practice answers (seed scores are sample data)</div></div></div>
 <div className="two-col"><div className="surface analytics-card"><h2>Application outcomes</h2><p>Observed counts across {total} recorded applications. Small samples are directional only.</p>{['Interview','Under review','Applied','Interested','Rejected','Offer'].map((status:string)=>{const n=data.applications.filter((a:Application)=>a.status===status).length;return <div className="outcome-row" key={status}><span>{status}</span><div className="progress-track"><i style={{width:(total?Math.max(n?8:0,n/total*100):0)+'%'}}/></div><b>{n}</b></div>})}<button className="secondary-button" onClick={()=>setPage('Application tracker')}>Review applications <ArrowRight size={14}/></button></div>
 <div className="surface analytics-card"><div className="section-head"><div><h2>Application intelligence</h2><p>Gemini findings from your recorded outcomes.</p></div><button className="secondary-button" onClick={run} disabled={busy}>{busy?'Analysing…':'Analyse with Gemini'} <Sparkles size={14}/></button></div>{error&&<p className="capacity-note">{error}</p>}{insights?<><span className="tag-chip">{insights.confidence} confidence · {total} records</span><p>{insights.summary}</p><p>{insights.dataQuality}</p><h3>Observed patterns</h3>{insights.observedPatterns.map((x:string,i:number)=><p key={i}>• {x}</p>)}<h3>Recommendations</h3>{insights.recommendations.map((x:string,i:number)=><p key={i}>→ {x}</p>)}{insights.roleInsights?.map((x:any,i:number)=><p key={i}>{x.role}: {x.applications} applications, {x.responses} responses, {x.interviews} interviews</p>)}{insights.resumeInsights?.map((x:any,i:number)=><p key={i}>Resume “{x.resumeVersion}”: {x.applications} applications, {x.responses} responses</p>)}</>:<div className="empty-chat"><b>No Gemini analysis yet</b><p>Run an analysis to get a cautious interpretation of your actual saved application history.</p></div>}</div></div></>}
function ProcessTracker({data,toggle,setPage,changeHours,analyzeProgress,approveChange,dismissChange}:any){const [analysis,setAnalysis]=useState<any>(null);const [analyzing,setAnalyzing]=useState(false);const [analysisError,setAnalysisError]=useState('');const analyze=async()=>{setAnalyzing(true);setAnalysisError('');try{setAnalysis(await analyzeProgress())}catch(e){setAnalysisError(e instanceof Error?e.message:'Gemini progress analysis failed')}finally{setAnalyzing(false)}};const done=data.tasks.filter((t:Task)=>t.done).length;const completion=Math.round(done/Math.max(data.tasks.length,1)*100);const projectProgress=Math.round(data.projects.reduce((sum: number,p:Project)=>sum+p.progress,0)/Math.max(data.projects.length,1));return <><div className="process-banner surface"><div className="process-copy"><span className="eyebrow"><span className="live-dot"/> YOUR MOMENTUM</span><h2>Every step moves you closer.</h2><p>Track the habits, projects, and practice that build readiness for <b>{data.role}</b>.</p><button className="primary-button" onClick={()=>setPage('Learning roadmap')}><BookOpen size={14}/> Continue this week’s plan <ArrowRight size={14}/></button></div><div className="process-ring" style={{'--progress':`${completion*3.6}deg`} as React.CSSProperties}><div><b>{completion}%</b><small>plan complete</small></div></div></div><div className="metric-grid process-metrics"><button className="metric-card process-stat" onClick={()=>setPage('Learning roadmap')}><div className="metric-top"><span>LEARNING TASKS</span><BookOpen size={16}/></div><div className="big-stat">{done}<span className="stat-divider">/</span>{data.tasks.length}</div><div className="progress-track"><i style={{width:`${completion}%`}}/></div><div className="stat-note">{data.tasks.filter((t:Task)=>!t.done).length} upcoming · {data.hours}h weekly availability</div></button><button className="metric-card process-stat" onClick={()=>setPage('Portfolio')}><div className="metric-top"><span>PORTFOLIO PROGRESS</span><FolderKanban size={16}/></div><div className="big-stat">{projectProgress}<span>%</span></div><div className="progress-track"><i style={{width:`${projectProgress}%`}}/></div><div className="stat-note">Across {data.projects.length} active projects</div></button><button className="metric-card process-stat" onClick={()=>setPage('Interview studio')}><div className="metric-top"><span>INTERVIEW PRACTICE</span><MessageSquareText size={16}/></div><div className="big-stat">{data.interviews.length}<span className="stat-label">sessions</span></div><div className="stat-note">Latest score {data.interviews.at(-1)||'—'} · track your growth</div></button><button className="metric-card process-stat" onClick={()=>setPage('Application tracker')}><div className="metric-top"><span>CAREER ACTIVITY</span><BriefcaseBusiness size={16}/></div><div className="big-stat">{data.applications.length}<span className="stat-label">applications</span></div><div className="stat-note">Pipeline updated as outcomes arrive</div></button></div><div className="process-grid"><div className="surface process-timeline"><div className="section-head"><div><h2>Milestone timeline</h2><p>Make progress at your pace. Check off a task when it’s done.</p></div><button className="text-action" onClick={()=>setPage('Learning roadmap')}>Open roadmap <ArrowRight size={13}/></button></div><div className="timeline-list">{data.tasks.map((task:Task,i:number)=><div className="timeline-item" key={task.id}><div className="timeline-rail"><span className={`timeline-point ${task.done?'finished':''}`}>{task.done?<Check size={11}/>:i+1}</span>{i<data.tasks.length-1&&<i/>}</div><div className={`timeline-content ${task.done?'finished-content':''}`}><span className="timeline-week">{task.week.toUpperCase()} · {task.skill.toUpperCase()}</span><b>{task.title}</b><small>{task.done?'Completed · readiness evidence captured':'Upcoming · part of your personalised plan'}</small></div><button className={`check-circle ${task.done?'checked':''}`} aria-label="Toggle milestone" onClick={()=>toggle(task.id)}>{task.done&&<Check size={12}/>}</button></div>)}</div></div><div className="process-side"><div className="surface process-side-card"><div className="section-head"><div><h2>Current focus</h2><p>One useful next action at a time.</p></div><span className="metric-icon purple"><Target size={16}/></span></div><div className="next-action"><span className="week-badge">NEXT UP</span><b>{data.tasks.find((t:Task)=>!t.done)?.title||'Choose a new learning milestone'}</b><p>Use a focused study block to close a priority skill gap, then add proof to your portfolio.</p><button className="secondary-button" onClick={()=>setPage('Skill gap analysis')}>Review skill priorities <ArrowRight size={13}/></button><button className="secondary-button" onClick={analyze} disabled={analyzing}>{analyzing?'Reviewing…':'Review progress with Gemini'} <Sparkles size={13}/></button>{analysisError&&<p className="capacity-note">{analysisError}</p>}{analysis&&<div className="progress-insight"><b>Gemini progress review</b><p>{analysis.reasoning}</p>{(data.pendingRoadmapChanges||[]).map((item:any,i:number)=><div className="progress-proposal" key={i}><small><b>{item.action}</b>: {item.reason} <br/>{item.impact}</small><button className="secondary-button" onClick={()=>approveChange(item)}>Accept</button><button className="text-action" onClick={()=>dismissChange(item)}>Dismiss</button></div>)}</div>}</div></div><div className="surface process-side-card"><div className="section-head"><div><h2>Weekly capacity</h2><p>Adjust time available for preparation.</p></div><Clock3 size={16}/></div><div className="capacity-control"><button onClick={()=>changeHours(Math.max(1,data.hours-1))}>−</button><b>{data.hours} <small>hours / week</small></b><button onClick={()=>changeHours(data.hours+1)}>+</button></div><p className="capacity-note">Changing availability updates the time estimate used by your learning plan.</p></div></div></div></>}
function Agent({data,command,setCommand,run,confirm,dismiss,edit,clearHistory,busy,error}:any){
 const pending=data.pendingAgentActions||[];
 const examples=['I have 10 hours a week. Move my prep plan to 10 hours and add a practical TensorFlow task for next week.','I finished the churn project, but missed two learning tasks. Review my progress and suggest what to change.','I applied to 12 backend internships, received 2 interviews and 4 rejections. What should I adjust?'];
 return <><div className="surface agent-hero"><span className="agent-large"><Sparkles size={24}/></span><div><div className="eyebrow"><span className="live-dot"/> CAREERPILOT INTELLIGENCE</div><h2>Your career, in conversation.</h2><p>Describe the whole situation—even if you change your mind mid-sentence. CareerPilot uses your saved context and shows proposed changes for review.</p></div></div><div className="agent-layout"><div className="surface conversation"><div className="section-head"><div><h2>Career agent</h2><p>Conversation and pending actions are saved in this browser.</p></div><button className="text-action" onClick={clearHistory} disabled={!data.chat.length}>Clear history</button></div><div className="chat-history" aria-live="polite">{data.chat.length===0?<div className="empty-chat"><span className="coach-icon"><Sparkles size={18}/></span><b>What would you like to work on?</b><p>Use your own words. Combine requests, include corrections, or explain the background.</p><div className="suggestion-chips">{examples.map((text:string)=><button key={text} onClick={()=>setCommand(text)}>{text}</button>)}</div></div>:data.chat.map((m:any,i:number)=><div className={m.role==='user'?'chat-message user-message':'chat-message'} key={i}><span className="chat-avatar">{m.role==='user'?'AM':<Sparkles size={14}/>}</span><div><b>{m.role==='user'?'You':'CareerPilot'}</b><p>{m.text}</p></div></div>)}</div>
 {busy&&<div className="agent-status" role="status"><span className="spinner"/> Reading your saved context and interpreting the request…</div>}{error&&<div className="agent-error" role="alert"><b>Couldn’t complete that request</b><span>{error}</span><small>Your message remains in the composer. Check the connection or try again.</small></div>}
 {pending.length>0&&<div className="surface skill-breakdown"><div className="section-head"><div><h2>Review before applying</h2><p>Edit an action, confirm it, or cancel it.</p></div><span className="tag-chip">{pending.length} pending</span></div>{pending.map((a:any)=><article className="agent-proposal" key={a.id}><div className="proposal-head"><span className="week-badge">{String(a.kind||'ACTION').replaceAll('_',' ').toUpperCase()}</span><span>From: {a.sourceText?.slice(0,90)||'Career conversation'}</span></div><label className="field-label">ACTION SUMMARY<input value={a.summary||''} onChange={e=>edit(a.id,{summary:e.target.value})}/></label>{a.kind==='update_hours'&&<label className="field-label">HOURS PER WEEK<input type="number" min="1" max="40" value={a.payload?.hours??''} onChange={e=>edit(a.id,{payload:{hours:Number(e.target.value)}})}/></label>}{a.kind==='add_task'&&<div className="proposal-fields"><label className="field-label">TASK TITLE<input value={a.payload?.title||''} onChange={e=>edit(a.id,{payload:{title:e.target.value}})}/></label><label className="field-label">WEEK<input value={a.payload?.week||''} onChange={e=>edit(a.id,{payload:{week:e.target.value}})}/></label></div>}{a.kind==='add_progress_note'&&<label className="field-label">NOTE<textarea rows={3} value={a.payload?.note||''} onChange={e=>edit(a.id,{payload:{note:e.target.value}})}/></label>}{a.kind==='progress_change'&&<><p className="proposal-reason">{a.payload?.title||a.payload?.week||a.payload?.action}</p>{a.payload?.hours!=null&&<label className="field-label">HOURS PER WEEK<input type="number" min="1" max="40" value={a.payload.hours} onChange={e=>edit(a.id,{payload:{hours:Number(e.target.value)}})}/></label>}{a.payload?.title&&<label className="field-label">TASK TITLE<input value={a.payload.title} onChange={e=>edit(a.id,{payload:{title:e.target.value}})}/></label>}</>}{a.kind==='add_projects'&&<div className="proposal-reason">{(a.payload?.projects||[]).map((p:any)=><p key={p.title}><b>{p.title}</b> · {(p.skills||[]).join(', ')}</p>)}</div>}<p className="proposal-reason"><b>Why:</b> {a.reason||'Based on your saved career context.'}{a.impact?` · ${a.impact}`:''}</p><div className="proposal-actions"><button className="primary-button" onClick={()=>confirm(a.id)}><Check size={13}/> Confirm action</button><button className="secondary-button" onClick={()=>dismiss(a.id)}><X size={13}/> Cancel</button></div></article>)}</div>}
 {data.progressNotes?.length>0&&<div className="surface analytics-card"><h2>Progress notes</h2>{data.progressNotes.slice(-4).reverse().map((n:any)=><p key={n.id}>{n.itemName?n.itemName+': ':''}{n.note}<small> · {new Date(n.createdAt).toLocaleDateString()}</small></p>)}</div>}
 <div className="agent-prompt-area"><div className="suggestion-chips">{examples.map((text:string)=><button key={text} onClick={()=>setCommand(text)}>{text}</button>)}</div><label className="sr-only" htmlFor="career-agent-input">Message CareerPilot</label><div className="agent-compose"><textarea id="career-agent-input" rows={3} value={command} onChange={e=>setCommand(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();run()}}} placeholder="Tell me what’s happening. Include multiple requests, corrections, or useful context…"/><button className="send-button" aria-label="Send message" onClick={run} disabled={busy||!command.trim()}>{busy?<span className="spinner"/>:<Send size={15}/>}</button></div><small className="compose-note">Enter for a new line · Ctrl/⌘ + Enter to send · Important changes wait for your confirmation</small></div></div><div className="agent-side"><div className="surface context-card"><h3>What I know about you</h3><div className="context-row"><Target size={15}/><span>Target role</span><b>{data.role}</b></div><div className="context-row"><Clock3 size={15}/><span>Study time</span><b>{data.hours}h / week</b></div><div className="context-row"><CheckCircle2 size={15}/><span>Learning tasks</span><b>{data.tasks.filter((t:Task)=>t.done).length}/{data.tasks.length}</b></div><div className="context-row"><FolderKanban size={15}/><span>Projects</span><b>{data.projects.length} tracked</b></div><div className="context-row"><MessageSquareText size={15}/><span>Interview reviews</span><b>{data.interviewReports?.length||0}</b></div><div className="context-row"><BriefcaseBusiness size={15}/><span>Applications</span><b>{data.applications.length} tracked</b></div></div><div className="surface privacy-card"><CircleHelp size={16}/><b>Your data stays yours</b><p>Career information stays in this browser. Gemini processes context through secure server routes.</p></div></div></div></>}
